R.insert(0, ("Pantry", "Spices & Seasoning", r"rose ?water|blossom water|orange blossom|kewra|flower water|vanilla (essence|extract)|essence"))
ORDER = ["Cat Food", "Dog Food", "Pet Care", "Diapers & Wipes", "Baby Food & Formula", "Baby Care", "Ice Cream", "Frozen Vegetables & Fruit",
         "Frozen Meat & Seafood", "Frozen Meals & Snacks", "Canned & Jarred Food", "Laundry", "Dishwashing", "Chocolate", "Milk & Plant Milk", "Butter, Ghee & Cream"]
_pos = {n: i for i, n in enumerate(ORDER)}
R = sorted(R, key=lambda r: (_pos.get(r[1], 1000) if r[1] in _pos else 1000))  # stable: listed subs first, rest keep order
_C = [(m, s, re.compile(p, re.I)) for m, s, p in R]
FOOD = {'Fruit & Vegetables', 'Meat & Seafood', 'Dairy & Eggs', 'Bakery', 'Frozen', 'Pantry', 'Snacks & Sweets', 'Beverages'}
NONFOOD = {'Personal Care', 'Household', 'Health & Wellness', 'Electronics', 'Home & Kitchen', 'Toys & Stationery', 'Fashion & Luggage'}
ALWAYS = {'Baby', 'Pets'}
STRONG = {'Laundry', 'Dishwashing'}   # clearly not food even when a shop files them under food

# Fallback: the coarse store category -> a main category with a general sub-category
FALLBACK_SUB = {
    "Fruit & Veg": ("Fruit & Vegetables", "Fresh Fruit & Vegetables"), "Dairy & Eggs": ("Dairy & Eggs", "Other Dairy"),
    "Meat & Fish": ("Meat & Seafood", "Other Meat & Seafood"), "Bakery": ("Bakery", "Other Bakery"),
    "Frozen Food": ("Frozen", "Other Frozen"), "Beverages": ("Beverages", "Other Drinks"), "Baby": ("Baby", "Baby Care"),
    "Pets": ("Pets", "Pet Care"), "Personal Care": ("Personal Care", "Personal Care & Accessories"),
    "Household": ("Household", "Cleaning Supplies"), "Health": ("Health & Wellness", "Pain Relief & First Aid"),
    "Electronics": ("Electronics", "Other Electronics"), "Stationery & Toys": ("Toys & Stationery", "Stationery & School"),
    "Fashion & Luggage": ("Fashion & Luggage", "Shoes, Bags & Accessories"),
    "Home & Kitchen": ("Home & Kitchen", "Dining & Storage"), "Pantry": ("Pantry", "Other Pantry"),
}


def classify(name, size="", fallback="Other"):
    t = f"{name} {size}".lower().replace("&amp;", "&")
    fb = FALLBACK_SUB.get(fallback, ("Other",))[0]   # the shop's own coarse category decides which side of the tree applies
    for main, sub, rx in _C:
        if main not in ALWAYS and sub not in STRONG:
            if fb in NONFOOD and main in FOOD: continue        # a "Personal Care" item is never food, whatever flavour it has
            if fb in FOOD and main in NONFOOD: continue
            if main == "Fruit & Vegetables" and fb not in ("Fruit & Vegetables", "Other"): continue
            if main == "Meat & Seafood" and fb not in ("Meat & Seafood", "Frozen", "Other", "Pantry"): continue
        if rx.search(t):
            return main, sub
    if fallback in FALLBACK_SUB:
        return FALLBACK_SUB[fallback]
    return "Other", "Other"


if __name__ == "__main__":
    print(classify("Almarai Full Fat Fresh Milk 1L"), classify("Colgate Toothpaste 100ml"), classify("Samsung Galaxy A15"))
